import { Book } from "@/lib/types";

export const hebrews: Book = {
  id: "hebrews",
  name: "Hebräer",
  shortName: "Hebr",
  testament: "new",
  introduction: `Der Brief vom Besseren\nDer jüdische Aufstand gegen die Römer, der im Jahr 66 n.Chr. begonnen hatte, wurde immer blutiger. Auch jüdische Parteien bekämpften sich untereinander. In Galiläa mussten Christen für einige Zeit ins Ostjordanland flüchten. Erst als die Römer die entsprechenden Gebiete erobert hatten, konnten sie zurückkommen.\nGegen Ende des Jahres 67 wurde Petrus in Rom hingerichtet. Timotheus, der dort eine Zeit lang in Haft war, kam nach dem Tod des Kaisers Nero im Jahr 68 frei (13,23). Irgendwo in Italien (13,24) wurde in dieser Zeit der **Hebräerbrief** geschrieben. Wer der Verfasser war, ist uns nicht bekannt. Der Brief ist an Christen gerichtet, die stark vom jüdischen Denken herkamen und in Gefahr standen, in ihren alten Glauben zurückzufallen.\n****Wie durch Jesus Christus alles sehr viel besser geworden ist als jede Einrichtung und jedes Opfer im Alten Testament.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Früher hat Gott viele Male und auf vielfältige Weise durch Propheten zu unseren Vorfahren gesprochen.", heading: "1: Der bessere Name\nJetzt redet Gott durch seinen Sohn" },
      { number: 2, text: "Doch am Ende dieser Zeiten sprach er durch den Sohn zu uns, den er zum Erben über alles eingesetzt hat und durch den er das ganze Universum erschuf." },
      { number: 3, text: "Seine Herrlichkeit leuchtet aus ihm und sein Wesen ist ihm völlig aufgeprägt. Durch die Macht seines Wortes trägt er das All. Und nachdem er das Opfer gebracht hat, das von Sünden reinigt, hat er den Ehrenplatz im Himmel eingenommen, den Platz an der rechten Seite der höchsten Majestät." },
      { number: 4, text: "Er steht so hoch über den Engeln, wie der Sohnesname, den er erbte, jeden Engelsnamen übertrifft." },
      { number: 5, text: "Oder hat Gott je zu einem der Engel gesagt: \"Du bist mein Sohn. Ich habe dich heute gezeugt.\"*? Oder: \"Ich werde ihm Vater und er wird mir Sohn sein\"*?", footnotes: ["Psalm 2,7", "2. Samuel 7,14; 1. Chronik 17,13"] },
      { number: 6, text: "Wenn er den Erstgeborenen aber wieder in die Welt einführt, sagt er: \"Alle Engel Gottes sollen ihn anbeten!\"*", footnotes: ["Psalm 97,7."] },
      { number: 7, text: "Von den Engeln heißt es zwar: \"Seine Engel macht er zu Sturmwinden, seine Diener zu Feuerflammen\"*,", footnotes: ["Psalm 104,4"] },
      { number: 8, text: "vom Sohn aber: \"Gott, dein Thron hat für immer Bestand. Dein Zepter bürgt für eine Herrschaft in Gerechtigkeit." },
      { number: 9, text: "Du hast das Recht geliebt und das Unrecht gehasst. Darum, Gott, hat dein Gott dich gesalbt mit dem Öl der Freude wie keinen deiner Begleiter.\"*", footnotes: ["Psalm 45,7-8."] },
      { number: 10, text: "Und: \"Du, Herr, hast am Anfang die Erde geschaffen und die Himmel mit deinen Händen geformt." },
      { number: 11, text: "Sie werden vergehen, du aber bleibst. Sie werden veralten wie ein Gewand." },
      { number: 12, text: "Wie einen Umhang wirst du sie zusammenrollen und wie ein Kleidungsstück sie auswechseln. Du aber bleibst der, der du bist, und deine Jahre enden nicht.\"*", footnotes: ["Psalm 102,26-28"] },
      { number: 13, text: "Oder hätte Gott jemals zu einem Engel gesagt: \"Setz dich an meine rechte Seite, bis ich deine Feinde zur Fußbank für dich gemacht habe\"*?", footnotes: ["Psalm 110,1"] },
      { number: 14, text: "Nein, die Engel sind alle nur Diener. Es sind Wesen der himmlischen Welt, die Gott als Helfer zu denen schickt, die an der kommenden Rettung teilhaben sollen." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Deshalb müssen wir im höchsten Maß auf das achten, was wir gehört haben, damit wir nicht am Ziel vorbeitreiben.", heading: "2: Der bessere Bote\nWir müssen ihm unbedingt zuhören!" },
      { number: 2, text: "Denn schon das Gesetz, das durch Engel verkündet wurde, war verbindlich, und wer es übertrat oder nicht darauf hören wollte, erhielt die verdiente Strafe." },
      { number: 3, text: "Wie sollen wir da der Strafe entgehen, wenn wir eine so großartige Rettungsbotschaft missachten? Es war ja der Herr selbst, durch den die Rettung zuerst verkündet wurde. Und uns wurde die Botschaft von denen bestätigt, die ihn mit eigenen Ohren gehört haben." },
      { number: 4, text: "Deren Zeugnis wiederum hatte Gott selbst durch Zeichen und Wundertaten und viele Beweise seiner Macht bestätigt, und auch dadurch, dass er den Heiligen Geist nach seinem Ermessen austeilte." },
      { number: 5, text: "Außerdem sind es nicht die Engel, denen er die zukünftige Welt, von der wir hier sprechen, unterstellt hat," },
      { number: 6, text: "denn es gibt eine Stelle in der Schrift, an der ausdrücklich gesagt wird: \"Was ist der Mensch, dass du, Gott, an ihn denkst? Was ist der Menschensohn, dass du für ihn sorgen solltest?" },
      { number: 7, text: "Für kurze Zeit hast du ihn geringer gemacht als die Engel, dann aber hast du ihn mit Herrlichkeit und Ehre gekrönt" },
      { number: 8, text: "und hast ihm alles unter die Füße gelegt.\"* Ihm hat Gott alles unterworfen. Es gibt nichts, worüber er nicht Herr wäre. Im Moment können wir das freilich noch nicht erkennen.", footnotes: ["Psalm 8,5-7"] },
      { number: 9, text: "Doch Jesus sehen wir bereits, der für kurze Zeit geringer als die Engel gemacht wurde und jetzt wegen seines Todesleidens mit Herrlichkeit und Ehre gekrönt ist. Denn er hatte den Tod auf sich genommen, damit auf diese Weise Gottes Gnade zu allen Menschen käme." },
      { number: 10, text: "Weil Gott viele Menschen als seine Kinder in die Herrlichkeit führen wollte, hat er den Wegbereiter ihrer Rettung durch Leiden vollkommen gemacht. Das war der angemessene Weg für ihn, der Ursprung und Ziel aller Dinge ist." },
      { number: 11, text: "Er, der heilig macht, und die, die von ihm geheiligt werden, haben nämlich alle denselben Vater. Deshalb schämt er sich auch nicht, sie seine Geschwister zu nennen." },
      { number: 12, text: "So sagt er zum Beispiel: \"Deinen Namen will ich meinen Brüdern bekannt machen; mitten in der Gemeinde will ich dir Loblieder singen.\"*", footnotes: ["Psalm 22,23"] },
      { number: 13, text: "oder: \"Ich will mein Vertrauen auf ihn setzen!\", und dann: \"Hier bin ich mit den Kindern, die Gott mir gegeben hat.\"*", footnotes: ["Jesaja 8,17-18"] },
      { number: 14, text: "Weil diese Kinder nun Menschen von Fleisch und Blut sind, ist auch er ein Mensch von Fleisch und Blut geworden. So konnte er durch seinen Tod den Teufel entmachten, der die Macht über den Tod hatte," },
      { number: 15, text: "und konnte die befreien, die durch Angst vor dem Tod ihr ganzes Leben lang versklavt waren." },
      { number: 16, text: "Außerdem wissen wir ja, dass er sich nicht für Engel einsetzt, sondern für die Nachkommen Abrahams." },
      { number: 17, text: "Deshalb musste er seinen Geschwistern in jeder Hinsicht gleich werden, um vor Gott ein barmherziger und treuer Hoher Priester für uns sein zu können; ein Hoher Priester, durch den die Sünden des Volkes gesühnt werden." },
      { number: 18, text: "Und weil er selbst gelitten hat, als er versucht wurde, kann er auch denen helfen, die in Versuchungen geraten." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Aus diesem Grund sollt ihr euer Augenmerk auf Jesus richten, liebe Geschwister, auf den Apostel* und Hohen Priester unseres Bekenntnisses. Ihr seid ja auch für Gott ausgesondert und zur Teilnahme an der himmlischen Welt berufen.", heading: "3: Der bessere Apostel\nAuf Jesus sehen!", footnotes: ["Apostel. Jesus wird hier selbst Apostel, Gesandter, genannt, weil er vom Vater auf die Erde gesandt worden war (siehe Johannes 20,21)."] },
      { number: 2, text: "Haltet euch vor Augen, wie treu er dem dient, der ihn eingesetzt hat. In dieser Hinsicht war er wie Mose, der ein treuer Diener für das ganze Haus Gottes war." },
      { number: 3, text: "Ihm jedoch kommt größere Ehre zu als Mose. Denn der Erbauer eines Hauses genießt größeren Ruhm als das Haus." },
      { number: 4, text: "Jedes Haus hat ja einen Erbauer, aber der, der alles erbaut hat, ist Gott." },
      { number: 5, text: "Und wenn Mose sich in Gottes ganzem Haus als treu erwies, bezieht sich das auf seinen Dienst als Verwalter. Damit war er ein Hinweis auf das, was später verkündigt werden sollte." },
      { number: 6, text: "Christus aber erweist seine Treue als Sohn und damit als Herr über das Haus Gottes. Und dieses Haus sind wir – vorausgesetzt, wir halten voll Zuversicht und Stolz an der Hoffnung fest, bis wir am Ziel sind." },
      { number: 7, text: "Darum beherzigt, was der Heilige Geist sagt: \"Wenn ihr heute die Stimme Gottes hört,", heading: "Auf Gott hören!" },
      { number: 8, text: "verschließt euch seinem Reden nicht, wie es das Volk in der Wüste an dem Tag tat, als es gegen ihn rebellierte.\"" },
      { number: 9, text: "\"Damals\", sagt Gott, \"haben eure Vorfahren mich herausgefordert und meine Geduld auf die Probe gestellt, obwohl sie vierzig Jahre lang meine Wunder gesehen hatten." },
      { number: 10, text: "Deshalb hat mich diese ganze Generation angewidert. 'Ihr Eigenwille führt sie ständig in die Irre', sagte ich, 'sie begreifen einfach nicht, welche Wege ich sie leiten will.'" },
      { number: 11, text: "Schließlich schwor ich in meinem Zorn: 'Sie werden niemals die Ruhe finden, die ich ihnen geben wollte!'\"*", footnotes: ["Psalm 95,7-11"] },
      { number: 12, text: "Achtet also darauf, liebe Geschwister, dass keiner von euch durch inneren Widerspruch dem Unglauben Raum gibt und sich von dem lebendigen Gott abwendet." },
      { number: 13, text: "Ermahnt euch gegenseitig jeden Tag, solange es dieses \"Heute\", von dem die Schrift spricht, noch gibt, damit niemand auf den Betrug der Sünde hereinfällt und hart wird." },
      { number: 14, text: "Denn wir gehören wirklich zum Messias und haben Anteil an allem, was ihm gehört – vorausgesetzt, wir halten die Zuversicht, die wir am Anfang hatten, mit aller Entschiedenheit fest." },
      { number: 15, text: "Noch einmal zu dem, was gesagt ist: \"Wenn ihr heute die Stimme Gottes hört, verschließt euch seinem Reden nicht, wie bei jener Rebellion.\"" },
      { number: 16, text: "Wer waren denn die Menschen, die sich gegen Gott auflehnten, obwohl sie seine Stimme hörten? Waren es nicht gerade die Leute, die Mose aus Ägypten geführt hatte?" },
      { number: 17, text: "Und wer erregte vierzig Jahre lang den Zorn Gottes? Waren es nicht gerade die, die gesündigt hatten und deren Leiber dann tot in der Wüste lagen?" },
      { number: 18, text: "Und wen meinte Gott mit seinem Schwur, dass sie nie die von ihm versprochene Ruhe finden würden – wenn nicht die, die ihm den Gehorsam verweigerten?" },
      { number: 19, text: "Wir sehen also, dass sie wegen ihres Unglaubens nicht hineinkamen." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Hüten wir uns also davor, zu meinen, jemand sei zu spät gekommen. Denn die Zusage, in Gottes Ruhe hineinzukommen, gilt ja noch. Wir müssen deshalb alles tun, dass so etwas nicht geschieht.", heading: "4: Die bessere Ruhe\nDas Ziel erreichen!" },
      { number: 2, text: "Denn die gute Botschaft wurde uns genauso verkündigt, wie jenen damals in der Wüste. Aber ihnen nützte es nichts, weil ihr Hören nicht mit Glauben verbunden war." },
      { number: 3, text: "Denn nur wir, die zum Glauben gefunden haben, werden in Gottes Ruhe hineinkommen, in die Ruhe, auf die Gott sich bezog als er sagte: \"So schwor ich in meinem Zorn: 'Sie werden niemals in meine Ruhe hineinkommen!'\"* Nun sind Gottes Werke zwar schon seit Vollendung der Schöpfung fertig,", footnotes: ["Psalm 95,11"] },
      { number: 4, text: "denn wo vom siebten Schöpfungstag die Rede ist, steht geschrieben: \"Am siebten Tag, nach Vollendung seiner Werke, ruhte Gott.\"*", footnotes: ["1. Mose 2,2"] },
      { number: 5, text: "Doch an der vorhin genannten Stelle sagte Gott: \"Sie werden niemals in meine Ruhe hineinkommen!\"" },
      { number: 6, text: "Es bleibt also dabei, dass einige in die Ruhe hineinkommen werden, obwohl die, denen die gute Botschaft damals gesagt wurde, durch ihren Ungehorsam ausgeschlossen blieben." },
      { number: 7, text: "Gott hat nun für eine neue Gelegenheit gesorgt, ein neues \"Heute\", von dem er lange nach jenem Geschehen durch David gesagt hat: \"Wenn ihr heute Gottes Stimme hört, verschließt euch seinem Reden nicht!\"" },
      { number: 8, text: "Denn wenn Josua das Volk schon in die eigentliche Ruhe hineingeführt hätte, würde Gott nicht später von einem anderen Tag geredet haben." },
      { number: 9, text: "Es gibt also noch eine besondere Ruhe* für das Volk Gottes.", footnotes: ["besondere Ruhe. Wörtlich: Sabbatruhe."] },
      { number: 10, text: "Denn wer in diese Ruhe hineinkommt, wird sich von all seiner Arbeit ausruhen, so wie Gott von der seinen ruht." },
      { number: 11, text: "Wir wollen deshalb alles dransetzen, zu dieser Ruhe zu gelangen, um nicht wie jene frühere Generation durch den gleichen Ungehorsam zu Fall zu kommen." },
      { number: 12, text: "Das Wort Gottes ist lebendig und wirksam. Es ist schärfer als das schärfste zweischneidige Schwert, das die Gelenke durchtrennt und das Knochenmark freilegt. Es dringt bis in unser Innerstes ein und trennt das Seelische vom Geistlichen. Es richtet und beurteilt die geheimen Wünsche und Gedanken unseres Herzens." },
      { number: 13, text: "Vor Gott ist ja nichts verborgen. Alles liegt nackt und bloß vor den Augen dessen da, vor dem wir Rechenschaft ablegen müssen." },
      { number: 14, text: "Weil wir nun einen großen Hohen Priester haben, der alle Himmel bis zum Thron des Höchsten durchschritten hat – Jesus, den Sohn Gottes –, lasst uns am Bekenntnis zu ihm festhalten!", heading: "4-7: Der bessere Priester\nAm Bekenntnis festhalten!" },
      { number: 15, text: "Dieser Hohe Priester versteht unsere Schwächen, weil ihm die gleichen Versuchungen begegnet sind wie uns – aber er blieb ohne Sünde." },
      { number: 16, text: "Darum wollen wir mit Zuversicht vor den Thron unseres überaus gnädigen Gottes treten, damit wir Gnade und Erbarmen finden und seine Hilfe zur rechten Zeit empfangen." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Denn jeder menschliche Hohe Priester wird für seine Mitmenschen eingesetzt. Er hat die Aufgabe, vor Gott für sie einzutreten und Gaben und Opfer für ihre Sünden darzubringen." },
      { number: 2, text: "Und weil er die menschliche Schwäche aus eigener Erfahrung kennt, kann er nachsichtig mit denen umgehen, die aus Unwissenheit oder Versehen vom richtigen Weg abgekommen sind." },
      { number: 3, text: "Deshalb muss er nicht nur für ihre, sondern auch für seine eigenen Sünden opfern." },
      { number: 4, text: "Niemand kann sich selbst zum Hohen Priester ernennen; man muss von Gott zu diesem Dienst berufen werden – wie es einst bei dem ersten Hohen Priester Aaron geschah." },
      { number: 5, text: "So hat auch der Messias sich nicht selbst die Würde eines Hohen Priesters verliehen, sondern es war der, der zu ihm gesagt hatte: \"Du bist mein Sohn. Ich habe dich heute gezeugt.\"*", footnotes: ["Psalm 2,7"] },
      { number: 6, text: "An einer anderen Stelle sagt Gott nämlich: \"Du sollst für immer Priester sein, ein Priester nach der Art des Melchisedek.\"*", footnotes: ["Psalm 110,4; vergleiche 1. Mose 14,18-20."] },
      { number: 7, text: "Als Jesus noch hier auf der Erde lebte, hat er unter Tränen und mit lautem Schreien gebetet und zu dem gefleht, der ihn aus der Gewalt des Todes retten konnte. Und wegen seiner ehrerbietigen Scheu vor Gott wurde er auch erhört." },
      { number: 8, text: "Obwohl er Gottes Sohn war, hat er an dem, was er durchmachen musste, gelernt, was Gehorsam bedeutet." },
      { number: 9, text: "Doch jetzt, wo er zur Vollendung gelangt ist, wurde er für alle, die ihm gehorchen, der Begründer des ewigen Heils." },
      { number: 10, text: "Und Gott selbst hat ihn als Hohen Priester begrüßt, einen Hohen Priester nach der Art des Melchisedek." },
      { number: 11, text: "Darüber könnten wir noch viel sagen, aber es lässt sich schwer darlegen, weil ihr nicht mehr richtig hinhören wollt.", heading: "Im Glauben erwachsen werden!" },
      { number: 12, text: "Eigentlich müsstet ihr längst andere unterrichten können, stattdessen braucht ihr jemand, der euch noch einmal die Anfangselemente der Botschaft Gottes beibringt. Ihr braucht wieder Milch statt fester Nahrung." },
      { number: 13, text: "Wer aber nur Milch verträgt, ist noch ein Kind. Er ist nicht in der Lage, die Lehre von der Gerechtigkeit Gottes zu begreifen." },
      { number: 14, text: "Feste Nahrung dagegen ist für Erwachsene, für reife Menschen, die durch ständigen Gebrauch geschärfte Sinne haben, um zwischen Gut und Böse zu unterscheiden." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Deshalb wollen wir jetzt die Lektionen vom Anfang unseres Lebens mit Christus hinter uns lassen und im Glauben erwachsen werden. Wir müssen euch doch nicht immer wieder erklären, wie wichtig es ist, sich von toten religiösen Werken abzuwenden und an Gott zu glauben." },
      { number: 2, text: "Ihr braucht keine weitere Unterweisung über die Bedeutung der Taufe im Unterschied zu anderen Waschungen, über die Handauflegung, die Auferstehung der Toten und das letzte Gericht mit seinem ewig gültigen Urteil." },
      { number: 3, text: "Nein, wir werden jetzt weitergehen; und wenn Gott will, wird es gelingen." },
      { number: 4, text: "Denn eins steht fest: Wenn Menschen schon einmal die Augen für die Wahrheit geöffnet bekamen, wenn sie die gute Gabe des Himmels gekostet haben und Anteil am Wirken des Heiligen Geistes erhielten," },
      { number: 5, text: "wenn sie schon Erfahrungen mit dem guten Wort Gottes und den Kräften der kommenden Welt machten" },
      { number: 6, text: "und sich dann doch wieder abgewendet haben, ist es unmöglich, sie wieder zur Änderung ihrer Einstellung zu bewegen. Denn sie nageln den Sohn Gottes praktisch noch einmal ans Kreuz und setzen ihn dem öffentlichen Spott aus." },
      { number: 7, text: "Wenn ein Stück Land durch häufigen Regen gut bewässert wird und nützliche Pflanzen für die wachsen lässt, die es bebaut haben, ist es von Gott gesegnet." },
      { number: 8, text: "Wenn es aber nichts als Dornen und Disteln hervorbringt, ist es unbrauchbar. Es zieht den Fluch Gottes auf sich und wird am Ende abgebrannt." },
      { number: 9, text: "Doch wir sind trotz des Gesagten überzeugt, liebe Geschwister, dass für euch der bessere Teil dieses Vergleichs zutrifft und eure Rettung keineswegs in Frage gestellt ist." },
      { number: 10, text: "Denn Gott ist nicht ungerecht. Er vergisst nicht, wie ihr ihm eure Liebe bewiesen und für ihn gearbeitet habt, indem ihr den anderen Gläubigen dientet und das noch immer tut." },
      { number: 11, text: "Wir wünschen nur, dass jeder von euch diesen Eifer bis ans Ende beweist, damit ihr voller Zuversicht an der Hoffnung festhalten könnt." },
      { number: 12, text: "Dann werdet ihr auch nicht träge, sondern folgt dem Vorbild derer, die durch Glauben und Geduld empfingen, was Gott ihnen zugesagt hatte." },
      { number: 13, text: "Ein Beispiel dafür ist Abraham. Als Gott ihm die Zusage machte, schwor er bei sich selbst, weil es keinen Größeren gibt, bei dem er hätte schwören können:" },
      { number: 14, text: "\"Ich versichere dir\", sagte er, \"ich werde dich mit Segen überschütten und dir eine zahllose Nachkommenschaft geben.\"*", footnotes: ["1. Mose 22,16-17"] },
      { number: 15, text: "Und so wartete Abraham geduldig und empfing schließlich, was Gott ihm versprochen hatte." },
      { number: 16, text: "Wenn Menschen schwören, tun sie das bei einem Größeren. Ihr Eid bekräftigt die Aussage und beseitigt jeden Widerspruch." },
      { number: 17, text: "So hat auch Gott sich mit einem Eid für seine Zusage verbürgt, denn er wollte den Erben dieses Versprechens die feste Gewissheit geben, dass er seine Zusage wirklich einlöst." },
      { number: 18, text: "Zwar ist es sowieso unmöglich, dass Gott lügen kann, doch hier wollte er sich in doppelter Weise festlegen – durch die Zusage und den Eid, die beide unumstößlich sind. Das ist für uns eine starke Ermutigung, denn wir haben ja unsere Zuflucht zu dieser Hoffnung genommen und wollen alles daran setzen, sie zu erreichen." },
      { number: 19, text: "In ihr haben wir einen sicheren und festen Anker, der uns mit dem Innersten des himmlischen Heiligtums verbindet." },
      { number: 20, text: "Dorthin ist Jesus bereits vorausgegangen, er, der unser ewiger Hoher Priester geworden ist, ein Hoher Priester nach der Art des Melchisedek." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Denn dieser Melchisedek war König von Salem und Priester des höchsten Gottes. Er ging Abraham entgegen, als dieser vom siegreichen Kampf gegen die Könige heimkehrte, und segnete ihn.", heading: "Unser Hoher Priester ist wie Melchisedek" },
      { number: 2, text: "Abraham gab ihm damals den zehnten Teil von seiner Beute. Der Name Melchisedek bedeutet \"König der Gerechtigkeit\", und König von Salem bedeutet \"König des Friedens\"." },
      { number: 3, text: "Es gibt keinen Hinweis auf seinen Vater, seine Mutter oder einen seiner Vorfahren. Es wird uns weder der Anfang noch das Ende seines Lebens mitgeteilt. Darin gleicht er dem Sohn Gottes und bleibt sozusagen für immer Priester." },
      { number: 4, text: "Wie groß dieser Mann war, seht ihr daran, dass selbst Abraham, der Stammvater unseres Volkes, ihm den zehnten Teil von seiner Beute gab." },
      { number: 5, text: "Nach den Bestimmungen des Gesetzes steht der Zehnte den Nachkommen Levis zu, denen das Priesteramt übertragen ist. Sie erheben ihn vom Volk, obwohl das ihre eigenen Brüder sind, also auch Nachkommen Abrahams wie sie." },
      { number: 6, text: "Melchisedek aber gehörte gar nicht zu Abrahams Volk und hat dennoch den Zehnten von Abraham entgegengenommen. Und außerdem hat er den Träger der Zusage gesegnet." },
      { number: 7, text: "Dabei ist zweifellos derjenige, der segnet, größer als der, der gesegnet wird." },
      { number: 8, text: "Im Fall der Leviten nehmen sterbliche Menschen den Zehnten entgegen, doch im Fall von Melchisedek einer, von dem bezeugt wird, dass er lebt." },
      { number: 9, text: "Man könnte sogar sagen, dass durch Abraham auch Levi den Zehnten gegeben hat, obwohl der doch normalerweise den Zehnten empfängt;" },
      { number: 10, text: "denn als Melchisedek und Abraham sich begegneten, war Levi als späterer Nachkomme Abrahams sozusagen schon dabei." },
      { number: 11, text: "Wenn nun das levitische Priestertum zur Vollkommenheit hätte führen können – denn das Gesetz, das unserem Volk gegeben wurde, beruhte ja darauf –, warum hätte Gott dann noch einen Priester einsetzen sollen, der zu einer ganz anderen Priesterordnung gehört, nämlich zu der von Melchisedek, anstatt zu der von Aaron?" },
      { number: 12, text: "Denn sobald das Priestertum geändert wird, ändert sich notwendigerweise auch das Gesetz." },
      { number: 13, text: "Denn der, von dem wir reden, gehört zu einem anderen Stamm, von dem nie jemand den Dienst am Altar versehen hat." },
      { number: 14, text: "Denn wie wir wissen, kommt unser Herr aus Juda. Doch Mose hat Juda nie in Verbindung mit dem Priestertum erwähnt." },
      { number: 15, text: "Das Ganze wird noch viel deutlicher, wenn sich die Einsetzung dieses Priesters – genau wie bei Melchisedek –" },
      { number: 16, text: "nicht auf eine vom Gesetz vorgeschriebene Abstammung gründet, sondern auf die Kraft eines unzerstörbaren Lebens." },
      { number: 17, text: "Denn die Schrift sagt über ihn: \"Du sollst für immer Priester sein, ein Priester nach der Art des Melchisedek.\"*", footnotes: ["Psalm 110,4"] },
      { number: 18, text: "Damit wird die frühere Bestimmung außer Kraft gesetzt, weil sie schwach und nutzlos war." },
      { number: 19, text: "Denn das Gesetz hat nichts zur Vollkommenheit führen können. Stattdessen wird etwas eingeführt, das uns eine viel bessere Hoffnung gibt und uns den ungehinderten Zugang zu Gott verschafft." },
      { number: 20, text: "Außerdem wurde der neue Priester durch einen Eid bestätigt. Bei den früheren Priestern gab es keinen solchen Eid." },
      { number: 21, text: "Nur ihm sagte Gott das Priestertum mit einem Eid zu: \"Der Herr hat geschworen und wird diese Zusage nie zurücknehmen: 'Du sollst für immer Priester sein, ein Priester nach der Art des Melchisedek.'\"*", footnotes: ["Psalm 110,4"] },
      { number: 22, text: "Deshalb ist Jesus auch der Garant eines besseren Bundes geworden." },
      { number: 23, text: "Es gibt noch einen weiteren Unterschied: Nach der alten Ordnung musste es viele Priester geben, denn wenn einer starb, musste ein anderer seinen Platz einnehmen." },
      { number: 24, text: "Jesus aber bleibt in Ewigkeit, sein Priestertum wird nie enden." },
      { number: 25, text: "Deshalb kann er auch alle, die durch ihn zu Gott kommen, vollkommen retten, weil er immer lebt, um sich für sie einzusetzen." },
      { number: 26, text: "Ein solcher Hoher Priester war auch für uns notwendig, einer, der vollkommen heilig und ohne Sünde ist, an dem Gott nichts auszusetzen hat; einer, der sich grundsätzlich von uns sündigen Menschen unterscheidet und den höchsten Ehrenplatz über allen Himmeln erhalten hat." },
      { number: 27, text: "Er muss nicht Tag für Tag Opfer darbringen wie die Hohen Priester vor ihm. Er muss auch nicht zuerst für die eigenen Sünden und dann für die des ganzen Volkes opfern. Nein, er hat das ein für allemal getan, als er sich selbst zum Opfer brachte." },
      { number: 28, text: "Das Gesetz konnte nur schwache, mit Fehlern behaftete Menschen zu Hohen Priestern machen, das Wort des Eidschwurs aber, das viel später als das Gesetz kam, ernannte den Sohn, der für immer und ewig vollkommen ist." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Der entscheidende Punkt bei allem Gesagten ist der: Wir haben diesen Hohen Priester, der sich auf den höchsten Ehrenplatz an der rechten Seite der göttlichen Majestät im Himmel gesetzt hat", heading: "8-9: Der bessere Bund" },
      { number: 2, text: "und der seinen Dienst im wahren Heiligtum versieht, in dem Zelt, das nicht von Menschen, sondern von Gott, dem Herrn, errichtet wurde." },
      { number: 3, text: "Jeder Hohe Priester wird ja eingesetzt, um Gaben und Opfer darzubringen. Deshalb muss auch unser Hoher Priester etwas haben, das er Gott opfern kann." },
      { number: 4, text: "Wäre er hier auf der Erde, dann wäre er nicht einmal Priester, denn hier gibt es schon Priester, die vom Gesetz dazu bestimmt sind, die Opfer darzubringen." },
      { number: 5, text: "Ihr Dienst vollzieht sich allerdings in einem Heiligtum, das nur ein Schatten, eine unvollkommene Nachbildung des himmlischen Heiligtums ist. Denn als Mose daranging, das heilige Zelt zu errichten, erhielt er von Gott die Weisung: \"Achte darauf, dass alles genau nach dem Vorbild angefertigt wird, das dir auf dem Berg gezeigt wurde.\"*", footnotes: ["2. Mose 25,40"] },
      { number: 6, text: "Der Dienst, der Jesus übertragen wurde, hat dagegen eine unvergleichlich größere Bedeutung. Er ist ja auch der Vermittler eines viel besseren Bundes geworden, der sich auf viel weitreichendere Zusagen stützt." },
      { number: 7, text: "Hätte der erste Bund keine Mängel gehabt, so wäre kein zweiter nötig gewesen." },
      { number: 8, text: "Denn Gott tadelte sein Volk als er sagte: \"Es wird ein Tag kommen, sagt der Herr, an dem ich mit dem Volk von Israel und dem Volk von Juda einen neuen Bund schließen werde." },
      { number: 9, text: "Er wird anders sein als der, den ich damals mit ihren Vätern schloss, als ich sie bei der Hand nahm und aus Ägypten herausführte. Denn diesem Bund sind sie nicht treu geblieben, und ich habe auch nicht mehr auf sie geachtet, spricht der Herr." },
      { number: 10, text: "Der neue Bund, den ich dann mit dem Volk Israel schließen will, wird so aussehen: Ich werde ihnen meine Gesetze in Herz und Gewissen schreiben. Ich werde ihr Gott und sie werden mein Volk sein." },
      { number: 11, text: "Keiner muss dann noch seinen Mitbürger belehren und niemand zu seinem Bruder sagen: 'Komm und lerne den Herrn kennen!' Denn alle – vom Kleinsten bis zum Größten – werden mich bereits kennen," },
      { number: 12, text: "weil ich ihnen ihr Unrecht vergebe und nie mehr an ihre Sünden denke.\"*", footnotes: ["Jeremia 31,31-34"] },
      { number: 13, text: "Wenn Gott also von einem neuen Bund spricht, hat er den ersten für veraltet erklärt. Was aber alt ist und ausgedient hat, wird bald verschwunden sein." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Nun hatte auch schon der erste Bund Vorschriften für den Gottesdienst und das irdische Heiligtum,", heading: "Der alte Bund hat ausgedient" },
      { number: 2, text: "das damals ein Zelt war. Es hatte einen vorderen Teil, das Heiligtum, in dem sich der Leuchter und der Tisch mit den geweihten Broten befanden." },
      { number: 3, text: "Dahinter lag, durch einen weiteren Vorhang abgetrennt, das sogenannte Höchstheilige." },
      { number: 4, text: "Dazu gehörten der goldene Räucheraltar und die ganz mit Gold überzogene Bundeslade, in der sich ursprünglich der goldene Krug mit dem Manna befand, der Stab Aarons, der Blüten getrieben hatte, und die beiden Steintafeln mit dem Bundesgesetz." },
      { number: 5, text: "Auf der Bundeslade standen zwei Cherubim*, die auf die Anwesenheit Gottes hinwiesen. Ihre Flügel breiteten sie über die Deckplatte der Lade aus, den Ort der Versöhnung. Aber davon soll jetzt nicht im Einzelnen die Rede sein.", footnotes: ["Cherub, Mehrzahl: Cherubim: Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert. Sie erscheinen vor allem dort, wo Gott persönlich gegenwärtig ist, siehe 2. Mose 25,17-21; Hesekiel 1 und 10."] },
      { number: 6, text: "So jedenfalls sah das Heiligtum aus. Jeden Tag gingen die Priester in den vorderen Teil des Zeltes, um dort ihre Pflichten zu erfüllen." },
      { number: 7, text: "Den hinteren Teil aber durfte nur der Hohe Priester betreten, und zwar nur ein einziges Mal im Jahr, und auch nicht ohne Blut. Dieses Blut opferte er für sich und für die Verfehlungen des Volkes." },
      { number: 8, text: "Damit macht der Heilige Geist deutlich, dass der Weg ins eigentliche Heiligtum solange nicht offen ist, wie die Bestimmungen des vorderen Zeltes gelten." },
      { number: 9, text: "Das Ganze ist nämlich ein Bild für unsere heutige Zeit: Die vom Gesetz verlangten Gaben und Opfer können das Gewissen der Opfernden nicht wirklich von Schuld befreien." },
      { number: 10, text: "Denn diese Vorschriften beziehen sich auf Essen und Trinken und rituelle Waschungen, also auf äußere Bestimmungen, die nur so lange gelten, bis eine neue und bessere Ordnung eingeführt wird." },
      { number: 11, text: "Aber jetzt ist Christus als Hoher Priester der wirklichen Heilsgüter gekommen. Er hat das größere und vollkommenere Zelt durchschritten, das nicht von Menschen gemacht wurde – also nicht von dieser Schöpfung ist –,", heading: "Christus bringt den neuen Bund" },
      { number: 12, text: "und hat das eigentliche Heiligtum ein für alle Mal betreten. Er kam auch nicht mit dem Blut von Böcken und Kälbern, sondern mit seinem eigenen Blut, und hat uns eine Erlösung gebracht, die für immer gilt." },
      { number: 13, text: "Zwar konnte auch das Blut von Böcken und Stieren oder die in Wasser aufgelöste Asche einer jungen Kuh einen Menschen von ritueller Unreinheit reinigen. Doch diese Reinheit war nur äußerlich." },
      { number: 14, text: "Das Blut des Christus bewirkt viel mehr, weil er sich in der Kraft des ewigen Geistes Gott als fehlerloses Opfer dargebracht hat. Sein Blut reinigt unser Gewissen von all diesen toten Werken, damit wir nun dem lebendigen Gott dienen." },
      { number: 15, text: "Christus ist also der Vermittler eines neuen Bundes, damit alle, die Gott berufen hat, als Erlöste das ewige Erbe empfangen können, das er ihnen zugesagt hat. Denn Christus ist in den Tod gegangen, um so für die Übertretungen zu bezahlen, die unter dem ersten Bund begangen wurden." },
      { number: 16, text: "Mit dem neuen Bund ist es wie mit einem Testament. Ein Testament kann erst vollstreckt werden, wenn der gestorben ist, der es aufgesetzt hat." },
      { number: 17, text: "Erst durch seinen Tod tritt es in Kraft; solange er lebt, hat es keine Bedeutung." },
      { number: 18, text: "Aus demselben Grund konnte schon der erste Bund nicht ohne Blut als Beweis für den Tod in Kraft treten." },
      { number: 19, text: "Denn nachdem Mose dem Volk alle Bestimmungen des Gesetzes vorgelesen hatte, nahm er das Blut von Kälbern und Böcken und besprengte mit Hilfe von Wasser, roter Wolle und Ysopzweigen* das Gesetzbuch und das ganze Volk.", footnotes: ["Ysop, ein Busch mit stark riechenden Blättern, der bei Reinigungsopfern zum Besprengen verwendet wurde. Seine Stängel werden bis zu 80 Zentimeter lang."] },
      { number: 20, text: "Dabei erklärte er: \"Das ist das Blut des Bundes, auf den Gott euch verpflichtet hat.\"*", footnotes: ["2. Mose 24,8"] },
      { number: 21, text: "Auch das heilige Zelt und alles, was für den Gottesdienst gebraucht wurde, besprengte Mose mit dem Blut." },
      { number: 22, text: "Nach dem Gesetz muss fast alles mit Blut gereinigt werden. Und ohne das Blut eines Opfers gibt es keine Vergebung." },
      { number: 23, text: "Mit solchen Mitteln müssen also die Einrichtungen des alten Bundes, die ja nur Abbilder der himmlischen Dinge sind, gereinigt werden. Die himmlischen Dinge selbst brauchen bessere Opfer.", heading: "9-10: Das bessere Opfer" },
      { number: 24, text: "Denn um sich vor Gott für uns einzusetzen, ist Christus ja nicht in ein von Menschen gemachtes Heiligtum eingetreten, eine Nachbildung des eigentlichen Heiligtums, sondern in den Himmel selbst." },
      { number: 25, text: "Er ging aber nicht in den Himmel, um sich immer wieder zu opfern, so wie der irdische Hohe Priester Jahr für Jahr mit dem Blut von Tieren das Höchstheilige betritt." },
      { number: 26, text: "Wenn das nötig gewesen wäre, hätte Christus seit Erschaffung der Welt viele Male leiden und sterben müssen. Er kam aber nur einmal in die Welt, jetzt, am Ende der Zeiten, um durch seinen Opfertod die Sünde zu beseitigen." },
      { number: 27, text: "Und so, wie jeder Mensch nur einmal sterben muss und dann vor das Gericht Gottes gestellt wird," },
      { number: 28, text: "so wurde auch der Messias nur einmal geopfert, um die Sünden vieler Menschen wegzunehmen. Wenn er zum zweiten Mal erscheinen wird, kommt er nicht mehr wegen der Sünde, sondern wird die endgültige Rettung für die bringen, die auf ihn warten." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Das Gesetz lässt also nur ein Schattenbild der künftigen Güter erkennen, nicht die Gestalt der Dinge selbst. Deshalb kann es die Menschen, die Jahr für Jahr mit denselben Opfern vor Gott hintreten, niemals völlig von ihrer Schuld befreien.", heading: "Nur Christus macht uns vollkommen" },
      { number: 2, text: "Hätte man sonst nicht längst mit den Opfern aufgehört? Denn der Opfernde wäre ja mit einem Mal rein, weil die Sünden sein Gewissen dann nicht mehr belasten würden." },
      { number: 3, text: "Doch das Gegenteil ist der Fall. Durch das Opfer wurden die Menschen jedes Jahr nur wieder an ihre Sünden erinnert." },
      { number: 4, text: "Das Blut von Stieren und Böcken ist eben nicht imstande, Sünden wegzunehmen." },
      { number: 5, text: "Deshalb sagte Christus bei seinem Eintritt in die Welt: \"Opfer und Gaben hast du nicht verlangt, doch einen Leib hast du mir gegeben." },
      { number: 6, text: "Über Brand- und Sündopfer freust du dich nicht." },
      { number: 7, text: "Da habe ich gesagt: 'Ja, ich bin bereit, mein Gott! Ich werde tun, was du willst – so, wie es in der Schrift von mir steht.'\"*", footnotes: ["Psalm 40,7-9"] },
      { number: 8, text: "Zuerst sagte er: \"Opfer und Gaben hast du nicht verlangt, über Brand- und Sündopfer freust du dich nicht\", obwohl diese Opfer doch vom Gesetz vorgeschrieben sind." },
      { number: 9, text: "Und dann fährt er fort: \"Ja, ich bin bereit! Ich werde tun, was du willst.\" Auf diese Weise hebt er die erste Ordnung auf, um die zweite in Kraft zu setzen." },
      { number: 10, text: "Und aufgrund dieses Willens sind wir geheiligt, weil Jesus Christus seinen Leib ein für alle Mal als Opfer dargebracht hat." },
      { number: 11, text: "Jeder andere Priester steht Tag für Tag vor dem Altar und bringt Gott viele Male die gleichen Opfer, die doch niemals Sünden wegnehmen können." },
      { number: 12, text: "Dieser Hohe Priester aber hat nur ein einziges Opfer für die Sünden dargebracht und sich dann für immer auf den Ehrenplatz an Gottes rechter Seite gesetzt." },
      { number: 13, text: "Dort wartet er, bis Gott ihm seine Feinde als Schemel unter die Füße legt." },
      { number: 14, text: "Denn mit einem einzigen Opfer hat er alle, die er für sich ausgesondert hat, völlig und für immer von ihrer Schuld befreit." },
      { number: 15, text: "Auch der Heilige Geist versichert uns das, denn er hat in der Schrift gesagt:" },
      { number: 16, text: "\"Der neue Bund, den ich dann mit ihnen schließen will, wird so aussehen: 'Ich werde ihnen meine Gesetze in Herz und Gewissen schreiben', spricht der Herr.\"" },
      { number: 17, text: "Und dann fährt er fort: \"Nie mehr werde ich an ihre Sünden und ihre Gesetzwidrigkeiten denken.\"*", footnotes: ["Jeremia 31,33-34"] },
      { number: 18, text: "Wo aber die Sünden vergeben sind, ist kein Opfer mehr nötig." },
      { number: 19, text: "Wir haben also jetzt einen freien und ungehinderten Zugang zum wirklichen Heiligtum, liebe Geschwister. Jesus hat ihn durch sein Blut für uns eröffnet.", heading: "Wir haben freien Zugang zu Gott" },
      { number: 20, text: "Er hat uns einen neuen Weg durch den Vorhang hindurch gebahnt, einen Weg, der zum Leben führt. Das war sein eigener Körper." },
      { number: 21, text: "Und wir haben auch einen Hohen Priester, dem das ganze Haus Gottes unterstellt ist." },
      { number: 22, text: "Deshalb wollen wir mit aufrichtigem Herzen voller Vertrauen und Zuversicht in die Gegenwart Gottes treten. Denn unsere Herzen wurden ja mit dem Blut von Christus* besprengt. Damit ist unser Gewissen von Schuld befreit und unser Körper mit dem Reinigungswasser gewaschen.", footnotes: ["mit dem Blut von Christus. Zusatz zur Verdeutlichung."] },
      { number: 23, text: "Wir wollen unbeirrbar an der Hoffnung festhalten, zu der wir uns bekennen. Denn auf Gott ist Verlass; er hält, was er zugesagt hat." },
      { number: 24, text: "Und lasst uns aufeinander achten und uns gegenseitig zur Liebe und zu guten Taten anspornen." },
      { number: 25, text: "Deshalb ist es wichtig, unsere Zusammenkünfte nicht zu versäumen, wie es sich schon einige angewöhnt haben. Wir müssen uns doch gegenseitig ermutigen, und das umso mehr, je näher ihr den Tag heranrücken seht, an dem der Herr kommt." },
      { number: 26, text: "Denn wenn wir absichtlich in Sünde leben, nachdem wir mit Gottes Hilfe die Wahrheit erkannt haben, verwerfen wir das einzige Opfer, das Sünden wegnehmen kann.", heading: "Werft das Vertrauen auf Christus nicht weg!" },
      { number: 27, text: "Dann bleibt nur noch das furchtbare Warten auf das Gericht und das wütende Feuer, das die verzehren wird, die sich gegen Gott gestellt haben." },
      { number: 28, text: "Schon wenn jemand das Gesetz des Mose absichtlich übertrat, gab es kein Mitgefühl. Er musste auf die Aussage von zwei oder drei Zeugen hin sterben." },
      { number: 29, text: "Was meint ihr denn, um wie viel schlimmer der bestraft werden muss, der den Sohn Gottes mit Füßen tritt und das Blut des Bundes entweiht, das ihn doch geheiligt hat, und der den Heiligen Geist verhöhnt, ohne den er Gottes Gnade nie erkannt hätte?" },
      { number: 30, text: "Denn wir kennen den, der gesagt hat: \"Die Rache gehört mir; ich werde vergelten!\", und auch: \"Der Herr wird sein Volk richten!\"*", footnotes: ["5. Mose 32,35-36; Psalm 135,14"] },
      { number: 31, text: "Es wird schrecklich sein, dem lebendigen Gott in die Hände zu fallen." },
      { number: 32, text: "Denkt doch einmal an die Zeit zurück, als Gott euch die Augen für die Wahrheit geöffnet hat. Damals musstet ihr so viel ertragen, und wie standhaft habt ihr durchgehalten.", heading: "10-12: Der bessere Weg" },
      { number: 33, text: "Einige von euch wurden öffentlich beleidigt und misshandelt; und die anderen standen denen, die das ertragen mussten, treu zur Seite." },
      { number: 34, text: "Ihr habt mit den Gefangenen mitgelitten. Und als man euch den Besitz wegnahm, habt ihr das mit Freude ertragen. Denn ihr wusstet, dass ihr etwas Besseres besitzt, was ihr nie verlieren werdet." },
      { number: 35, text: "Werft diese Zuversicht doch jetzt nicht weg - und mit ihr eine so große Belohnung!" },
      { number: 36, text: "Was ihr braucht, ist Standhaftigkeit. Denn wenn ihr weiterhin nach Gottes Willen handelt, werdet ihr alles bekommen, was er euch zugesagt hat." },
      { number: 37, text: "\"Es ist nur noch eine ganz, ganz kurze Zeit, dann wird der kommen, der kommen soll\", hat Gott gesagt," },
      { number: 38, text: "und: \"Durch seinen Glauben wird der Gerechte leben.\" Und: \"Wenn er sich abwendet, werde ich keine Freude an ihm haben.\"*", footnotes: ["Habakuk 2,3-4; sinngemäß nach der LXX zitiert."] },
      { number: 39, text: "Doch wir gehören nicht zu denen, die sich abwenden und so in ihr Verderben rennen. Nein, wir gehören zu denen, die glauben und so das Leben gewinnen." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Was ist also der Glaube? Er ist die Grundlage unserer Hoffnung, ein Überführtsein von Wirklichkeiten, die man nicht sieht.", heading: "Was Glaube ist" },
      { number: 2, text: "Darin haben unsere Vorfahren gelebt und die Anerkennung Gottes gefunden." },
      { number: 3, text: "Aufgrund des Glaubens verstehen wir, dass die Welt durch Gottes Befehl entstand, dass also das Sichtbare aus dem Unsichtbaren kam." },
      { number: 4, text: "Aufgrund des Glaubens brachte Abel ein besseres Opfer dar als Kain. Deshalb nahm Gott seine Gaben an und stellte ihm das Zeugnis aus, vor ihm bestehen zu können. Durch seinen Glauben redet er heute noch, obwohl er doch gestorben ist.", heading: "Vorbilder des Glaubens" },
      { number: 5, text: "Aufgrund des Glaubens wurde Henoch in den Himmel aufgenommen, ohne zu sterben. Niemand konnte ihn mehr finden, weil Gott ihn zu sich genommen hatte. Bevor die Schrift von diesem Geschehen berichtet, stellt sie ihm das Zeugnis aus, dass sein Leben Gott gefallen hatte.*", footnotes: ["1. Mose 5,24"] },
      { number: 6, text: "Aber ohne Glauben ist es unmöglich, Gott zu gefallen. Wer zu Gott kommen will, muss glauben, dass es ihn gibt und dass er die belohnt, die ihn aufrichtig suchen." },
      { number: 7, text: "Aufgrund des Glaubens baute Noah eine Arche, um seine Familie zu retten. Er gehorchte der göttlichen Weisung in ehrfürchtiger Scheu, obwohl von dem angedrohten Unheil noch nichts zu sehen war. Durch dieses Vertrauen auf Gott verurteilte er die damalige Welt und wurde ein Erbe jener Gerechtigkeit, die aus dem Glauben stammt." },
      { number: 8, text: "Aufgrund des Glaubens gehorchte Abraham dem Ruf Gottes. Er verließ seine Heimat und zog in ein anderes Land, das Gott ihm zum Erbbesitz geben wollte. Er ging, ohne zu wissen, wohin er kommen würde." },
      { number: 9, text: "Aufgrund des Glaubens siedelte er sich in dem zugesagten Land an, auch wenn er dort wie ein Fremder lebte und mit Isaak und Jakob, denen Gott dieselbe Zusage gegeben hatte, in Zelten wohnte." },
      { number: 10, text: "Er wartete auf die Stadt, die feste Fundamente hat, deren Baumeister und Schöpfer Gott selbst ist." },
      { number: 11, text: "Aufgrund des Glaubens erhielt selbst Sara die Kraft, Mutter zu werden, obwohl sie unfruchtbar war und schon ein Alter erreicht hatte, in dem sie nicht mehr schwanger werden konnte. Sie war nämlich überzeugt, dass Gott sein Versprechen halten würde." },
      { number: 12, text: "Deshalb stammt auch von einem einzigen Mann, noch dazu von einem, der schon so gut wie tot war, ein ganzes Volk ab, ein Volk, so unzählbar wie die Sterne am Himmel und wie die Sandkörner am Ufer des Meeres." },
      { number: 13, text: "All diese Menschen haben Gott bis zu ihrem Tod vertraut, obwohl sie noch nicht erhielten, was er ihnen zugesagt hatte. Doch sie sahen die Erfüllung der Zusagen von fern und freuten sich darauf. Ganz offen sagten sie, dass sie hier auf der Erde nur Gäste und Fremde seien." },
      { number: 14, text: "Damit gaben sie zu verstehen, dass sie noch auf der Suche nach einer Heimat waren." },
      { number: 15, text: "Hätten sie dabei an das Land gedacht, aus dem sie gekommen waren, dann hätten sie genügend Zeit gehabt, dorthin zurückzukehren." },
      { number: 16, text: "Aber sie suchten nach etwas Besserem, einer Heimat im Himmel. Deshalb schämt Gott sich nicht, ihr Gott genannt zu werden, denn er hat ihnen eine Stadt im Himmel gebaut." },
      { number: 17, text: "Aufgrund des Glaubens war Abraham bereit, Isaak zu opfern, als Gott ihn auf die Probe stellte. Abraham, der die Zusage Gottes empfangen hatte, war bereit, seinen einzigen Sohn zu opfern," },
      { number: 18, text: "obwohl Gott ihm versprochen hatte: \"Durch Isaak gebe ich dir die zugesagte Nachkommenschaft.\"*", footnotes: ["1. Mose 21,12"] },
      { number: 19, text: "Denn Abraham ging davon aus, dass Gott Isaak wieder zum Leben erwecken konnte. Und bildlich gesprochen hat er seinen Sohn ja auch vom Tod zurückerhalten." },
      { number: 20, text: "Aufgrund des Glaubens segnete Isaak seine Söhne Jakob und Esau im Blick auf das, was kommen würde." },
      { number: 21, text: "Aufgrund des Glaubens segnete Jakob auf seinem Sterbebett jeden der Söhne Josefs besonders; und auf seinen Stab gestützt neigte er sich anbetend vor Gott." },
      { number: 22, text: "Aufgrund des Glaubens sprach Josef kurz vor seinem Tod vom Auszug der Israeliten aus Ägypten und bestimmte, was dann mit seinen Gebeinen geschehen sollte." },
      { number: 23, text: "Aufgrund des Glaubens wurde Mose nach seiner Geburt drei Monate lang von seinen Eltern versteckt gehalten. Sie sahen seine Schönheit und hatten keine Angst, dem Befehl des Königs zu trotzen." },
      { number: 24, text: "Aufgrund des Glaubens wollte Mose, als er groß geworden war, sich nicht mehr Sohn der Pharaotochter nennen lassen." },
      { number: 25, text: "Lieber wollte er mit dem Volk Gottes misshandelt werden, als sich dem flüchtigen Genuss der Sünde hinzugeben." },
      { number: 26, text: "Er war sicher, dass die Schätze Ägyptens nicht so viel wert waren wie die Schmach, die auch der Messias trug. Denn er sah auf die Belohnung, die Gott für ihn bereithielt." },
      { number: 27, text: "Aufgrund des Glaubens verließ er Ägypten, ohne sich vor dem Zorn des Königs zu fürchten. Er ging entschlossen seinen Weg, weil er den unsichtbaren Gott vor Augen hatte." },
      { number: 28, text: "Aufgrund des Glaubens führte er das Passafest* ein und ließ das Blut der Passalämmer an die Türpfosten streichen, damit der todbringende Engel ihre Erstgeborenen nicht antastete.", footnotes: ["Passa. Siehe 2. Mose 12-13"] },
      { number: 29, text: "Aufgrund des Glaubens zogen die Israeliten durch das Rote Meer als wäre es trockenes Land. Als die Ägypter das auch versuchten, gingen sie unter." },
      { number: 30, text: "Aufgrund des Glaubens stürzten die Mauern Jerichos ein, nachdem die Israeliten sieben Tage um die Stadt gezogen waren." },
      { number: 31, text: "Aufgrund des Glaubens blieb die Hure Rahab vor dem Untergang Jerichos bewahrt. Sie hatte die Kundschafter freundlich aufgenommen, während die anderen Einwohner sich Gott widersetzten." },
      { number: 32, text: "Wie viele andere wären noch zu nennen! Doch die Zeit würde mir fehlen, wenn ich von Gideon und Barak erzählen wollte, von Simson, Jiftach und David, von Samuel und den Propheten." },
      { number: 33, text: "Aufgrund des Glaubens haben sie Königreiche niedergezwungen, für Gerechtigkeit gesorgt und bekommen, was Gott ihnen versprochen hatte. Sie verschlossen Löwen das Maul," },
      { number: 34, text: "löschten glühendes Feuer und entkamen dem tödlichen Schwert. Aus Schwäche gewannen sie Kraft, im Kampf wurden sie stark und schlugen feindliche Heere zurück." },
      { number: 35, text: "Es kam sogar vor, dass Frauen ihre verstorbenen Angehörigen durch Auferstehung zurückerhielten .Andere dagegen, die auch Gott vertrauten, wurden zu Tode gefoltert. Sie wollten eine bessere Auferstehung erhalten als sich von Gott loszusagen und freizukommen." },
      { number: 36, text: "Wieder andere ertrugen Spott und Auspeitschungen, Ketten und Gefängnis." },
      { number: 37, text: "Sie wurden gesteinigt, zersägt und mit dem Schwert umgebracht. Heimatlos zogen sie umher, in Schaf- und Ziegenfelle gehüllt, Not leidend, bedrängt, misshandelt." },
      { number: 38, text: "Die Welt war es nicht wert, solche Menschen zu tragen, die dann auch noch in der Wüste und in den Bergen, in Höhlen und in Klüften ihre Zuflucht suchen mussten." },
      { number: 39, text: "Doch sie alle, die durch ihr Vertrauen auf Gott ein rühmliches Zeugnis erhielten, haben die Erfüllung der Zusagen nicht erlebt," },
      { number: 40, text: "und zwar deshalb, weil Gott für unsere Zeit etwas Besseres vorgesehen hat. Deshalb können sie erst zusammen mit uns die Vollendung erreichen." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Wir sind also von einer ganzen Wolke von Zeugen umgeben. Deshalb wollen auch wir den Wettkampf bis zum Ende durchhalten und jede Last ablegen, die uns behindert, besonders die Sünde, die uns so leicht umschlingt.", heading: "Werdet nicht müde!" },
      { number: 2, text: "Und dabei wollen wir auf Jesus schauen. Er hat gezeigt, wie der Glaubenslauf beginnt und wie er zum Ziel führt. Weil er wusste, welche Freude auf ihn wartete, hat er das Kreuz und die Schande dieses Todes auf sich genommen. Nun sitzt er auf dem Ehrenplatz an Gottes rechter Seite." },
      { number: 3, text: "Schaut euch an, wie er die Anfeindung sündiger Menschen ertragen hat. Dann werdet auch ihr nicht müde und verliert nicht den Mut." },
      { number: 4, text: "Immerhin habt ihr im Kampf gegen die Sünde noch nicht das Leben lassen müssen." },
      { number: 5, text: "Trotzdem werdet ihr schon mutlos. Habt ihr denn ganz vergessen, was Gott zu seinen Kindern sagt: \"Mein Sohn, missachte nicht die strenge Hand des Herrn, werde nicht mutlos, wenn er dich zurechtweist!" },
      { number: 6, text: "Denn es ist so: Wen der Herr liebt, den erzieht er streng, und wen er als Sohn annimmt, dem gibt er auch Schläge.\"*", footnotes: ["Sprüche 3,11-12; nach der LXX zitiert."] },
      { number: 7, text: "Was ihr ertragen müsst, dient also eurer Erziehung. Gott behandelt euch so wie ein Vater seine Söhne. Oder habt ihr je von einem Sohn gehört, der nie bestraft wurde?" },
      { number: 8, text: "Wenn Gott euch nicht mit strenger Hand erziehen würde, wie er das bei allen macht, dann hätte er euch nicht als Kinder anerkannt." },
      { number: 9, text: "Auch unsere menschlichen Väter hatten uns streng erzogen. Trotzdem achteten wir sie. Müssen wir uns nicht noch viel mehr dem Vater des Geistes unterordnen, um geistliches Leben zu haben?" },
      { number: 10, text: "Unsere leiblichen Väter haben uns auch nur für kurze Zeit in Zucht genommen, und zwar so, wie es ihren Vorstellungen entsprach. Unser himmlischer Vater aber weiß wirklich, was zu unserem Besten dient. Er erzieht uns, damit wir Anteil an seiner Heiligkeit bekommen." },
      { number: 11, text: "Jede Bestrafung tut weh. Sie ist alles andere als eine Freude. Später jedoch trägt eine solche Erziehung reiche Frucht: Menschen, die durch diese Schule gegangen sind, führen ein friedfertiges und gerechtes Leben." },
      { number: 12, text: "Stärkt also eure müden Hände und die zitternden Knie" },
      { number: 13, text: "und geht auf geraden Wegen, damit lahm gewordene Füße nicht auch noch verrenkt, sondern vielmehr geheilt werden!" },
      { number: 14, text: "Bemüht euch ernstlich um Frieden mit allen und um ein geheiligtes Leben, ohne das niemand den Herrn sehen wird." },
      { number: 15, text: "Achtet aufeinander, damit niemand sich von Gottes Gnade ausschließt! Lasst nicht zu, dass eine bittere Wurzel zur Giftpflanze wird, durch die dann viele von euch zu Schaden kommen!" },
      { number: 16, text: "Achtet auch darauf, dass keiner von euch ein ausschweifendes Leben führt oder mit heiligen Dingen so geringschätzig umgeht wie Esau, der für eine einzige Mahlzeit sein Erstgeburtsrecht verkaufte!" },
      { number: 17, text: "Ihr wisst, wie es ihm später erging, als er den Segen von seinem Vater bekommen wollte: Er wurde von Gott verworfen und fand keine Möglichkeit mehr, das rückgängig zu machen, obwohl er sich unter Tränen darum bemühte." },
      { number: 18, text: "Nun habt ihr Gott nicht so erfahren wie die Israeliten damals am Berg Sinai. Sie kamen zu einem Berg, den man anfassen konnte, auf dem ein Feuer loderte und der in dunkle Wolken gehüllt war. Es herrschte Finsternis und ein Sturm tobte." },
      { number: 19, text: "Sie hörten einen gewaltigen Posaunenschall und eine mächtige Stimme, vor der sie sich so fürchteten, dass sie darum baten, kein weiteres Wort mehr hören zu müssen." },
      { number: 20, text: "Sie wichen zurück, als Gott anordnete: \"Wenn auch nur ein Tier den Berg berührt, soll es gesteinigt werden.\"*", footnotes: ["2. Mose 19,13"] },
      { number: 21, text: "Das ganze Geschehen war so Furcht erregend, dass selbst Mose sagte: \"Ich zittere vor Angst.\"*", footnotes: ["5. Mose 9,19"] },
      { number: 22, text: "Ihr dagegen seid zum Berg Zion und zur Stadt des lebendigen Gottes gekommen, zu dem Jerusalem im Himmel, wo sich unzählbare Engelscharen zu einem Fest versammelt haben." },
      { number: 23, text: "Ihr seid zur Gemeinde der erstgeborenen Kinder Gottes gekommen, deren Namen im Himmel aufgeschrieben sind. Ihr seid zu Gott selbst gekommen, dem Richter von allen und zu den Gerechten, die schon am Ziel sind, denn ihr Geist ist bei Gott." },
      { number: 24, text: "Ihr seid zu Jesus gekommen, dem Vermittler eines neuen Bundes, und zu dem Reinigungsblut, das viel besser redet als das Blut Abels." },
      { number: 25, text: "Hütet euch also davor, den abzuweisen, der zu euch spricht. Schon die Israeliten entkamen ihrer Strafe nicht, als sie den abwiesen, der von einem Ort auf der Erde zu ihnen sprach. Wie viel schlimmer wird es uns ergehen, wenn wir den ablehnen, der vom Himmel her zu uns spricht." },
      { number: 26, text: "Damals erschütterte seine Stimme die Erde, aber jetzt hat er angekündigt: \"Ich werde noch einmal eine Erschütterung kommen lassen, aber nicht nur über die Erde, sondern auch über den Himmel.\"*", footnotes: ["Haggai 2,6"] },
      { number: 27, text: "Die Worte \"noch einmal\" zeigen, dass bei dieser Erschütterung die ganze geschaffene Welt umgewandelt werden soll; bleiben wird nur das, was nicht erschüttert werden kann." },
      { number: 28, text: "Auf uns wartet also ein unerschütterliches Reich. Deshalb wollen wir dankbar sein, denn dadurch dienen wir Gott, wie es ihm gefällt: in Ehrfurcht und heiliger Scheu." },
      { number: 29, text: "Denn auch unser Gott ist ein verzehrendes Feuer." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Die geschwisterliche Liebe möge euch ganz erhalten bleiben!", heading: "13: Leben mit dem Besseren" },
      { number: 2, text: "Vergesst nicht, Gastfreundschaft zu üben! Denn auf diese Weise haben einige, ohne es zu wissen, Engel bei sich aufgenommen." },
      { number: 3, text: "Denkt an die Gefangenen, als wärt ihr selbst mit im Gefängnis, und an die Misshandelten, als wär's euer eigener Körper!" },
      { number: 4, text: "Haltet die Ehe in Ehren und bleibt einander treu! Denn Menschen, die in sexueller Unmoral und fortwährendem Ehebruch leben, werden von Gott gerichtet." },
      { number: 5, text: "Lasst nicht die Geldgier euer Leben bestimmen! Begnügt euch mit dem, was ihr habt! Denn Gott hat gesagt: \"Nie werde ich dich aufgeben, niemals dich im Stich lassen.\"*", footnotes: ["5. Mose 31,6"] },
      { number: 6, text: "Deshalb können wir getrost sagen: \"Der Herr steht mir bei, nun fürchte ich nichts! Was kann ein Mensch mir schon tun?\"*", footnotes: ["Psalm 118,6 nach der LXX zitiert."] },
      { number: 7, text: "Denkt an eure Führer, die euch damals das Wort Gottes gebracht haben. Erinnert euch an das, was aus ihrem Leben hervorgegangen ist, und nehmt euch ihren Glauben zum Vorbild." },
      { number: 8, text: "Denn Jesus Christus ist immer derselbe – gestern, heute und in alle Ewigkeit." },
      { number: 9, text: "Lasst euch nicht von irgendwelchen fremden Lehren mitreißen! Denn es ist gut, durch die Gnade Gottes stark zu werden und nicht durch das Befolgen von Speisegeboten. Sich daran zu halten, hat noch niemand Nutzen gebracht." },
      { number: 10, text: "Wir haben einen Altar, an dem die Priester des irdischen Heiligtums keinen Anteil haben." },
      { number: 11, text: "Denn die Körper der Tiere, deren Blut vom Hohen Priester zur Sühnung der Sünden ins innere Heiligtum hineingebracht wird, werden ja draußen vor dem Lager verbrannt." },
      { number: 12, text: "Deshalb musste auch Jesus außerhalb der Stadtmauern leiden, um durch sein Blut das Volk zu heiligen." },
      { number: 13, text: "Lasst uns also zu ihm hinausgehen, vor das Lager, und die Schande ertragen, die auch er getragen hat!" },
      { number: 14, text: "Denn hier auf der Erde haben wir keine Heimat. Unsere Sehnsucht gilt jener künftigen Stadt, zu der wir unterwegs sind." },
      { number: 15, text: "Durch Jesus wollen wir Gott ein immer währendes Dankopfer bringen, denn das Lob aus unserem Mund ist unser Bekenntnis zu ihm." },
      { number: 16, text: "Vergesst auch nicht, Gutes zu tun und mit anderen zu teilen! Denn solche Opfer gefallen Gott." },
      { number: 17, text: "Hört auf eure Führer in der Gemeinde und fügt euch ihren Weisungen! Es ist ihre Aufgabe, über eure Seelen zu wachen, und sie werden Gott einmal Rechenschaft über ihren Dienst geben müssen. Sorgt also dafür, dass sie ihre Aufgabe mit Freude tun können, anstatt mit Seufzen und Stöhnen, denn das wäre sicher nicht gut für euch." },
      { number: 18, text: "Betet für uns! Wir sind überzeugt, ein gutes Gewissen zu haben, denn wir möchten in jeder Weise ein Leben führen, wie es gut und richtig ist." },
      { number: 19, text: "Gerade jetzt brauche ich eure Gebete besonders, weil ich hoffe, dann umso eher wieder zu euch zu kommen." },
      { number: 20, text: "Es ist der Gott des Friedens, der den großen Hirten seiner Schafe von den Toten zurückbrachte, unseren Herrn Jesus, und der mit dessen Blut den ewigen Bund in Kraft setzte." },
      { number: 21, text: "Er rüste euch mit allem Guten aus, damit ihr seinen Willen tun könnt. Durch Jesus Christus möge er das, was ihm gefällt, in euch bewirken. Ihm sei die Ehre für immer und ewig. Amen." },
      { number: 22, text: "Ich bitte euch, liebe Geschwister, weist dieses Wort der Ermutigung nicht ab! Ich habe mich ja so kurz wie möglich gefasst." },
      { number: 23, text: "Ihr sollt wissen, dass unser Bruder Timotheus freigelassen worden ist. Wenn er rechtzeitig hier eintrifft, werden wir euch gemeinsam besuchen." },
      { number: 24, text: "Grüßt eure Führer und die ganze Gemeinde der Heiligen. Die Geschwister aus Italien lassen euch grüßen." },
      { number: 25, text: "Die Gnade sei mit euch allen!" },
    ] },
  ],
};